import math

def sum_of_divisors(n):
    """Calculates sigma(n), the sum of divisors of n."""
    s = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            s += i
            j = n // i
            if i != j:
                s += j
    return s

def get_divisors(n):
    """Returns a list of all divisors of n."""
    divs = []
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.append(i)
            j = n // i
            if i != j:
                divs.append(j)
    return sorted(divs)

def check_sigma_square(m):
    """Checks if sigma(m) is a perfect square."""
    sigma_m = sum_of_divisors(m)
    sqrt_sigma = math.isqrt(sigma_m)
    return sqrt_sigma * sqrt_sigma == sigma_m, sigma_m, sqrt_sigma

# Search for the first few values of m > 1
limit = 100 # Let's check up to m=100 initially

results = []
for m in range(2, limit + 1):
    is_square, sigma_m, _ = check_sigma_square(m)
    if is_square:
        divisors = get_divisors(m)
        results.append({
            'm': m,
            'sigma(m)': sigma_m,
            'divisors': divisors
        })

print("First few values of m > 1 such that sigma(m) is a perfect square:")
for res in results:
    print(f"m = {res['m']}, sigma(m) = {res['sigma(m)]} = {int(math.isqrt(res['sigma(m)]))}^2. Divisors: {res['divisors']}")

